"""Check the exact test-only SF07 inventory in one Cargo output."""
import collections
import pathlib
import re
import sys

EXPECTED = ['security_sf07_private::indexed::tests::all_eighty_patricia_positions_and_full_replacement', 'security_sf07_private::indexed::tests::certificate_above_u64_and_exact_idle', 'security_sf07_private::indexed::tests::detected_summary_link_and_freelist_corruption_faults', 'security_sf07_private::indexed::tests::differential_semantic_decisions_and_retired_identities', 'security_sf07_private::indexed::tests::empty_first_padding_and_leftmost_not_earliest_due', 'security_sf07_private::indexed::tests::exact_count_bytes_work_and_native_overflow', 'security_sf07_private::indexed::tests::foreign_brand_and_exhausted_brand_do_not_admit', 'security_sf07_private::indexed::tests::full_tree_replacement_reuses_branch_and_single_slot', 'security_sf07_private::indexed::tests::inherited::production_clock_path_and_close_are_usable', 'security_sf07_private::indexed::tests::inherited::r01_burst_two_refills_exactly_one_token_per_interval', 'security_sf07_private::indexed::tests::inherited::r02_refill_boundary_minus_one_then_exact_interval', 'security_sf07_private::indexed::tests::inherited::r03_huge_elapsed_saturates_before_token_subtraction', 'security_sf07_private::indexed::tests::inherited::r04_zero_and_oversized_rule_settings_fail_startup', 'security_sf07_private::indexed::tests::inherited::r05_denials_do_not_slide_or_reset_bucket_debt', 'security_sf07_private::indexed::tests::inherited::r06_depleted_subject_debt_cannot_be_evicted', 'security_sf07_private::indexed::tests::inherited::r07_full_refill_and_idle_allow_one_fixed_slot_reuse', 'security_sf07_private::indexed::tests::inherited::r08_partial_refill_is_not_evicted_or_reset', 'security_sf07_private::indexed::tests::inherited::r09_subject_buckets_are_separated_by_trusted_domain_id', 'security_sf07_private::indexed::tests::inherited::r11_subject_table_stays_fixed_and_refuses_untracked_subjects', 'security_sf07_private::indexed::tests::inherited::r12_backward_clock_fault_is_sticky_and_preserves_bucket', 'security_sf07_private::indexed::tests::inherited::r13_elapsed_conversion_failure_is_sticky_without_refill_or_charge', 'security_sf07_private::indexed::tests::inherited::r14_controlled_clock_is_sampled_under_transition_lock', 'security_sf07_private::indexed::tests::inherited::r15_arc_handles_share_one_owner_but_separate_owner_has_fresh_state', 'security_sf07_private::indexed::tests::inherited::r16_close_preserves_debt_and_prevents_sampling_or_new_key', 'security_sf07_private::indexed::tests::inherited::r18_three_simultaneous_same_tick_charges_accept_exact_burst', 'security_sf07_private::indexed::tests::key_width_endpoints_and_shared_last_bit', 'security_sf07_private::indexed::tests::panic_after_mutations_restores_debt_and_poison_closes', 'security_sf07_private::indexed::tests::request_transitions_allocate_zero_and_native_profiles_fit', 'security_sf07_private::indexed::tests::runtime_guard_rolls_back_every_cut_and_stays_faulted', 'security_sf07_private::legacy_rate::tests::production_clock_path_and_close_are_usable', 'security_sf07_private::legacy_rate::tests::r01_burst_two_refills_exactly_one_token_per_interval', 'security_sf07_private::legacy_rate::tests::r02_refill_boundary_minus_one_then_exact_interval', 'security_sf07_private::legacy_rate::tests::r03_huge_elapsed_saturates_before_token_subtraction', 'security_sf07_private::legacy_rate::tests::r04_zero_and_oversized_rule_settings_fail_startup', 'security_sf07_private::legacy_rate::tests::r05_denials_do_not_slide_or_reset_bucket_debt', 'security_sf07_private::legacy_rate::tests::r06_depleted_subject_debt_cannot_be_evicted', 'security_sf07_private::legacy_rate::tests::r07_full_refill_and_idle_allow_one_fixed_slot_reuse', 'security_sf07_private::legacy_rate::tests::r08_partial_refill_is_not_evicted_or_reset', 'security_sf07_private::legacy_rate::tests::r09_subject_buckets_are_separated_by_trusted_domain_id', 'security_sf07_private::legacy_rate::tests::r11_subject_table_stays_fixed_and_refuses_untracked_subjects', 'security_sf07_private::legacy_rate::tests::r12_backward_clock_fault_is_sticky_and_preserves_bucket', 'security_sf07_private::legacy_rate::tests::r13_elapsed_conversion_failure_is_sticky_without_refill_or_charge', 'security_sf07_private::legacy_rate::tests::r14_controlled_clock_is_sampled_under_transition_lock', 'security_sf07_private::legacy_rate::tests::r15_arc_handles_share_one_owner_but_separate_owner_has_fresh_state', 'security_sf07_private::legacy_rate::tests::r16_close_preserves_debt_and_prevents_sampling_or_new_key', 'security_sf07_private::legacy_rate::tests::r18_three_simultaneous_same_tick_charges_accept_exact_burst', 'security_sf07_private::quota::tests::claim_sum_overflow_is_capacity_without_counter_mutation', 'security_sf07_private::quota::tests::q01_two_resource_partial_full_is_atomic', 'security_sf07_private::quota::tests::q03_catalog_byte_product_rejects_overflow_and_isize_boundary', 'security_sf07_private::quota::tests::q04_duplicate_is_invalid_but_bad_resource_id_faults_closed', 'security_sf07_private::quota::tests::q05_exact_count_and_bytes_boundary_releases_one_claim', 'security_sf07_private::quota::tests::q06_moved_reservation_releases_once_at_final_drop', 'security_sf07_private::quota::tests::q09_poisoned_disposal_releases_claim_and_keeps_fault_latched', 'security_sf07_private::quota::tests::q13_two_simultaneous_claims_have_one_winner', 'security_sf07_private::quota::tests::startup_rejects_zero_and_empty_catalog']

text = pathlib.Path(sys.argv[1]).read_text(encoding="utf-8")
summaries = re.findall(r"test result: ok\. (\d+) passed; (\d+) failed; (\d+) ignored;", text)
assert summaries == [("55", "0", "0")], "expected exactly 55 passing private SF07 tests"
observed = re.findall(r"^test (security_sf07_private::\S+) \.\.\. ok$", text, re.M)
assert collections.Counter(observed) == collections.Counter(EXPECTED), "SF07 inventory mismatch"
